var n=`1208-sopa-de-pata`;var a=`world-1208`;var t=`SV`;var r=`central-america-caribbean`;var s=4;var o=173;var l={en:`Sopa de Pata`,ua:`Суп де пата`};var d={en:`Sopa de Pata is a dish from El Salvador featuring beef tripe, beef shank, yellow onion, garlic. This home-sized recipe records each ingredient at the step where it is used. Beef shank replaces traditional cow feet; the gelatin-rich hoof texture will be different.`,ua:`Суп де пата, страва кухні країни Сальвадор з такими основними складниками: яловичий рубець, яловича гомілка, жовта цибуля, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Яловича гомілка замінює традиційні коров’ячі ноги; драглиста текстура буде іншою.`};var g=[{en:`Simmer thoroughly cleaned tripe and beef shank in fresh water, skim repeatedly and cook until very tender; avoid handling raw offal without proper sanitation.`,ua:`Варіть ретельно очищений рубець та яловичу гомілку у свіжій воді, знімайте піну й доведіть до цілковитої м’якості; дотримуйтеся гігієни під час роботи із субпродуктами.`,t:[`simmering`,`skimming-foam`],m:130,i:[[`beef-tripe`,550,`g`],[`beef-shank`,650,`g`],[`water`,2300,`ml`],[`yellow-onion`,200,`g`],[`garlic`,5,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`potato`,300,`g`],[`carrot`,250,`g`],[`plantain`,260,`g`],[`ground-cumin`,5,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,30,`g`],[`lime`,2,`pcs`]]}];var h={slug:n,id:a,country:`SV`,region:r,servings:4,minutes:173,title:l,text:d,steps:g};export{t as country,h as default,a as id,o as minutes,r as region,s as servings,n as slug,g as steps,d as text,l as title};